import{_ as o,C as e,o as s,c as d,j as t,E as l,a as r,a2 as n}from"./chunks/framework.C21TwvGF.js";const v=JSON.parse(`{"title":"3-hafta (Mentor)","description":"","frontmatter":{"title":"3-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"10-sinf (BI & ML)","link":"/mentor/10-sinf-bi/"},"n":3,"bob":"I-bob · Ma’lumotlar muhandisligiga kirish va ma’lumotlarni boshqarish","lessons":[{"g":7,"title":"7-dars: Relyatsion jadvallar, Primary Key, Foreign Key va relyatsion yaxlitlik","lead":"Ma'lumotlar bazasining go'zalligi uning tartibida va qat'iy intizomidadir. Agar jadvalda to'g'ri kalitlar va cheklovlar o'rnatilmasa, u tez orada tartibsiz raqamlar uyumiga aylanadi. Ushbu darsda biz relyatsion arxitekturaning asosi bo'lgan cheklovlar, Primary Key turlari, Composite kalitlar hamda bog'langan yozuvlar xavfsizligini ta'minlashni o'rganamiz.","link":"/mentor/10-sinf-bi/hafta-03/dars-1","slide":"/slaydlar/10-sinf-bi/hafta-03/dars-1.html","test":"/slaydlar/10-sinf-bi/hafta-03/dars-1-test.html"},{"g":8,"title":"8-dars: R-diagrammalar (ERD) loyihalash va SQLite bilan ishlash","lead":"Yaxshi loyihalangan ma'lumotlar bazasi — mustahkam bino poydevoriga o'xshaydi. Agar poydevor egri bo'lsa, ustiga qancha go'zal bino qurmang, u ertami-kechmi qulaydi. Ushbu darsda biz murakkab tizimlarning arxitekturasini qog'ozda va ekranda ERD (Entity-Relationship Diagram) ko'rinishida modellashtirishni hamda O'zbekiston ta'limi bo'yicha «Maktab tahliliy platformasi»ning relyatsion poydevorini qurishni o'rganamiz.","link":"/mentor/10-sinf-bi/hafta-03/dars-2","slide":"/slaydlar/10-sinf-bi/hafta-03/dars-2.html","test":"/slaydlar/10-sinf-bi/hafta-03/dars-2-test.html"},{"g":9,"title":"9-dars: SQL analitik operatorlari: SELECT, WHERE, ORDER BY, LIMIT asoslari","lead":"Ma'lumotlar bazasi — bu ulkan kutubxona. SELECT, WHERE, ORDER BY va LIMIT operatorlari esa shu kutubxonaning to'g'ri kitobni topib beradigan aqlli kutubxonachisidir. Ushbu darsda biz O'zbekiston ta'limi statistikasini SQL orqali tahlil qilishni o'rganamiz: eng ko'p o'quvchisi bo'lgan viloyatlarni topish, diapazonli filtrlash va TOP-N reytinglar chiqarish.","link":"/mentor/10-sinf-bi/hafta-03/dars-3","slide":"/slaydlar/10-sinf-bi/hafta-03/dars-3.html","test":"/slaydlar/10-sinf-bi/hafta-03/dars-3-test.html"}],"test":"/slaydlar/10-sinf-bi/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"mentor/10-sinf-bi/hafta-03/index.md","filePath":"mentor/10-sinf-bi/hafta-03/index.md"}`),h={name:"mentor/10-sinf-bi/hafta-03/index.md"},c={class:"blk"},g={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},u={class:"blk"},b={id:"baholash-mezoni-1",tabindex:"-1"};function y(m,a,k,p,q,f){const i=e("Icon");return s(),d("div",null,[t("div",c,[t("h2",g,[l(i,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=n("",23))]),t("div",u,[t("h2",b,[l(i,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni-1","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=n("",30))])])}const z=o(h,[["render",y]]);export{v as __pageData,z as default};
